/* Pixel Roman Converter - 4-color retro palette:
   - Deep Slate: #1a1c23
   - Parchment Gray: #f0f2ea
   - Pixel Gold: #e2b714
   - Pixel Ruby (Error): #d64045
*/

[hidden] {
  display: none !important;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: #1a1c23;
  background-image: 
    linear-gradient(#242733 1px, transparent 1px),
    linear-gradient(90deg, #242733 1px, transparent 1px);
  background-size: 20px 20px;
  color: #f0f2ea;
  font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.container {
  width: 100%;
  max-width: 480px;
}

.card {
  background-color: #242733;
  border: 4px solid #f0f2ea;
  box-shadow: 6px 6px 0px 0px #000000;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.header {
  text-align: center;
  border-bottom: 3px dashed #3a3f52;
  padding-bottom: 16px;
}

.title {
  font-size: 1.35rem;
  letter-spacing: 1px;
  color: #e2b714;
  text-transform: uppercase;
  line-height: 1.3;
}

.subtitle {
  margin-top: 6px;
  font-size: 0.85rem;
  color: #a4acb9;
}

.converter-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.field-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 0.9rem;
  font-weight: bold;
  color: #f0f2ea;
  letter-spacing: 0.5px;
}

.pixel-input {
  background-color: #1a1c23;
  color: #f0f2ea;
  font-family: inherit;
  font-size: 1.15rem;
  padding: 12px;
  border: 3px solid #f0f2ea;
  box-shadow: 3px 3px 0px 0px #000000;
  outline: none;
  width: 100%;
  transition: border-color 0.1s, box-shadow 0.1s;
}

.pixel-input.uppercase {
  text-transform: uppercase;
}

.pixel-input:hover {
  border-color: #e2b714;
}

.pixel-input:focus {
  border-color: #e2b714;
  box-shadow: 3px 3px 0px 0px #e2b714;
}

.swap-indicator {
  text-align: center;
  font-size: 1.5rem;
  color: #e2b714;
  user-select: none;
  line-height: 1;
}

.status-box {
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #1a1c23;
  border: 2px solid #3a3f52;
  padding: 8px 12px;
  text-align: center;
}

.status-text {
  font-weight: bold;
  letter-spacing: 1px;
  font-size: 0.95rem;
  color: #a4acb9;
}

.status-text.error {
  color: #d64045;
}

.status-text.valid {
  color: #e2b714;
}

.button-group {
  display: flex;
  justify-content: flex-end;
}

.pixel-btn {
  background-color: #e2b714;
  color: #1a1c23;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  border: 3px solid #f0f2ea;
  box-shadow: 3px 3px 0px 0px #000000;
  padding: 10px 18px;
  cursor: pointer;
  outline: none;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.pixel-btn:hover {
  background-color: #f7ce3e;
}

.pixel-btn:focus-visible {
  outline: 2px solid #f0f2ea;
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px 0px #000000;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .title {
    font-size: 1.15rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const numberInput = document.getElementById('number-input');
  const romanInput = document.getElementById('roman-input');
  const statusText = document.getElementById('status-text');
  const clearBtn = document.getElementById('clear-btn');

  const ROMAN_MAP = [
    { value: 1000, symbol: 'M' },
    { value: 900, symbol: 'CM' },
    { value: 500, symbol: 'D' },
    { value: 400, symbol: 'CD' },
    { value: 100, symbol: 'C' },
    { value: 90, symbol: 'XC' },
    { value: 50, symbol: 'L' },
    { value: 40, symbol: 'XL' },
    { value: 10, symbol: 'X' },
    { value: 9, symbol: 'IX' },
    { value: 5, symbol: 'V' },
    { value: 4, symbol: 'IV' },
    { value: 1, symbol: 'I' }
  ];

  // Strict standard Roman numeral syntax pattern for values 1 to 3999
  const ROMAN_REGEX = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

  let isUpdating = false;

  function setStatus(message, type) {
    statusText.textContent = message;
    statusText.className = 'status-text' + (type ? ' ' + type : '');
  }

  function toRoman(num) {
    if (!Number.isInteger(num) || num < 1 || num > 3999) {
      return null;
    }
    let result = '';
    let remaining = num;
    for (let i = 0; i < ROMAN_MAP.length; i++) {
      while (remaining >= ROMAN_MAP[i].value) {
        result += ROMAN_MAP[i].symbol;
        remaining -= ROMAN_MAP[i].value;
      }
    }
    return result;
  }

  function fromRoman(str) {
    const cleanStr = str.trim().toUpperCase();
    if (!cleanStr || !ROMAN_REGEX.test(cleanStr)) {
      return null;
    }

    let sum = 0;
    let i = 0;
    while (i < cleanStr.length) {
      const twoChar = cleanStr.substring(i, i + 2);
      const matchedTwo = ROMAN_MAP.find(entry => entry.symbol === twoChar);
      if (matchedTwo) {
        sum += matchedTwo.value;
        i += 2;
        continue;
      }

      const oneChar = cleanStr.substring(i, i + 1);
      const matchedOne = ROMAN_MAP.find(entry => entry.symbol === oneChar);
      if (matchedOne) {
        sum += matchedOne.value;
        i += 1;
        continue;
      }

      return null;
    }

    if (sum < 1 || sum > 3999) {
      return null;
    }

    // Verify canonical representation (e.g. rejects improper duplicate combinations)
    if (toRoman(sum) !== cleanStr) {
      return null;
    }

    return sum;
  }

  numberInput.addEventListener('input', () => {
    if (isUpdating) return;
    isUpdating = true;

    const rawValue = numberInput.value.trim();
    if (rawValue === '') {
      romanInput.value = '';
      setStatus('Ready', '');
      isUpdating = false;
      return;
    }

    const num = Number(rawValue);
    if (Number.isInteger(num) && num >= 1 && num <= 3999) {
      const roman = toRoman(num);
      romanInput.value = roman;
      setStatus(num + ' = ' + roman, 'valid');
    } else {
      romanInput.value = '';
      setStatus('Not valid', 'error');
    }

    isUpdating = false;
  });

  romanInput.addEventListener('input', () => {
    if (isUpdating) return;
    isUpdating = true;

    const rawRoman = romanInput.value.trim().toUpperCase();
    if (rawRoman === '') {
      numberInput.value = '';
      setStatus('Ready', '');
      isUpdating = false;
      return;
    }

    const num = fromRoman(rawRoman);
    if (num !== null) {
      numberInput.value = num;
      setStatus(rawRoman + ' = ' + num, 'valid');
    } else {
      numberInput.value = '';
      setStatus('Not valid', 'error');
    }

    isUpdating = false;
  });

  clearBtn.addEventListener('click', () => {
    numberInput.value = '';
    romanInput.value = '';
    setStatus('Ready', '');
    numberInput.focus();
  });
});
